<?php
namespace App\Console\Commands;
use App\Models\BackupRun;use Illuminate\Console\Command;use Illuminate\Support\Str;
class RecordBackupRun extends Command{protected $signature='dms:backup-record {type : DATABASE|DOCUMENTS|FULL} {status : STARTED|SUCCESS|FAILED|VERIFIED|RESTORE_TESTED} {--ulid=} {--manifest-sha256=} {--location-class=OFFSITE} {--error=}';protected $description='Record infrastructure-controlled backup/verification evidence without exposing backup credentials';public function handle():int{$run=$this->option('ulid')?BackupRun::where('ulid',$this->option('ulid'))->first():null;if(!$run){$run=BackupRun::create(['ulid'=>(string)Str::ulid(),'backup_type'=>strtoupper($this->argument('type')),'status'=>'STARTED','location_class'=>$this->option('location-class'),'started_at'=>now()]);}$status=strtoupper($this->argument('status'));$updates=['status'=>$status];if(in_array($status,['SUCCESS','FAILED'],true))$updates['completed_at']=now();if($status==='VERIFIED')$updates['verified_at']=now();if($status==='RESTORE_TESTED')$updates['restore_tested_at']=now();if($this->option('manifest-sha256'))$updates['manifest_sha256']=$this->option('manifest-sha256');if($this->option('error'))$updates['error_message']=$this->option('error');$run->update($updates);$this->line($run->ulid);return self::SUCCESS;}}
